function kruskal(n, edges) {
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  edges.sort((a, b) => a[2] - b[2]);
  let cost = 0;
  const mst = [];
  for (const [u, v, w] of edges) {
    const ru = find(u), rv = find(v);
    if (ru !== rv) {
      parent[ru] = rv;
      mst.push([u, v, w]);
      cost += w;
    }
  }
  return { cost, mst};
}

