int unite(int a, int b) {
    int ra=find(a), rb=find(b);
    if (ra==rb)return 0;
    if (rnk[ra]<rnk[rb])par[ra]=rb;
    else if (rnk[ra]>rnk[rb])par[rb]=ra;
    else {
        par[rb]=ra;
        rnk[ra]++;
    }
