#include <vector>
#include <algorithm>
using namespace std;
struct Edge {
    int u, v, w;
};
vector<int>par, rnk;
int find(int x) {
    return par[x]==x?x:(par[x]=find(par[x]));
}
vector<Edge> kruskal(int V, vector<Edge>&edges) {
    par.resize(V);
    rnk.resize(V, 0);
    iota(par.begin(), par.end(), 0);
    sort(edges.begin(), edges.end(), [](auto&a, auto&b){return a.w<b.w; });
    vector<Edge>mst;
    for (auto&e:edges) {
        int ra=find(e.u), rb=find(e.v);
        if (ra!=rb) {
            if (rnk[ra]<rnk[rb])par[ra]=rb;
            else if (rnk[ra]>rnk[rb])par[rb]=ra;
            else {
                par[rb]=ra;
                rnk[ra]++;
            }
            mst.push_back(e);
        }
    }
    return mst;
}
